# -*- coding: utf-8 -*-
import json

chunk4 = {
  "JAP_build_up_the_manchurian_army_desc": "[MAN.GetNameDefCap] akan berada di garis terdepan dalam setiap perang di utara. Kita harus memastikan mereka cukup tangguh untuk menahan setiap potensi serangan musuh.",
  "JAP_non_aggression_pact_with_china": "Pakta Non-Agresi dengan Tiongkok",
  "JAP_non_aggression_pact_with_china_desc": "Meskipun hubungan kita dengan Tiongkok secara historis penuh ketegangan, kini kita membutuhkan pakta non-agresi dengan mereka demi membebaskan pasukan untuk serbuan ke utara.",
  "JAP_create_a_manchurian_imperial_air_force": "Bentuk Angkatan Udara Kekaisaran Manchuria",
  "JAP_create_a_manchurian_imperial_air_force_desc": "Keunggulan udara adalah kunci memenangkan perang. Jika [MAN.GetNameDef] memiliki angkatan udara sendiri, hal ini akan sangat membantu meringankan beban udara kita.",
  "JAP_technological_exchange": "Pertukaran Teknologi",
  "JAP_technological_exchange_desc": "Kita memerlukan sekutu untuk menghadapi sang beruang kutub. Jerman bukan hanya kandidat yang tepat, tetapi juga memiliki kemajuan teknologi melimpah yang dapat dibagikan kepada kita demi membantu perjuangan kita.",
  "JAP_preemptive_war": "Perang Preemtif",
  "JAP_preemptive_war_desc": "Dengan memalsukan laporan peningkatan agresi [SOV.GetAdjective] di perbatasan utara, kita dapat menciptakan dalih untuk melancarkan serangan preemtif demi menumpas ancaman utara.",
  "JAP_establish_the_northern_resource_area": "Bentuk Kawasan Sumber Daya Utara",
  "JAP_establish_the_northern_resource_area_desc": "Hamparan luas Siberia yang kaya mineral harus dieksploitasi demi menyokong mesin perang kita yang terus membesar.",
  "JAP_german_rocketry": "Teknologi Roket Jerman",
  "JAP_german_rocketry_desc": "Kemajuan teknologi roket Jerman akan sangat berguna bagi upaya perang kita. Kita harus berusaha memperoleh cetak biru ini, berapa pun harganya.",
  "JAP_strengthen_civilian_government": "Perkuat Pemerintahan Sipil",
  "JAP_tora_tora_tora_idea": "Tora! Tora! Tora!",
  "JAP_tora_tora_tora_idea_desc": "Setelah pukulan telak pembuka mereka, pihak Jepang melancarkan kampanye kilat agresif menggunakan kekuatan armada kapal induk mereka.",
  "JAP_strengthen_civilian_government_desc": "Nilai-nilai liberalisme dan demokrasi yang kian berkembang bukanlah ancaman bagi bangsa kita, melainkan justru dapat menjadi kekuatan terbesarnya. Kita harus memperkuat pemerintahan agar dapat melindungi cita-cita luhur ini.",
  "JAP_ally_with_the_zaibatsus": "Bersekutu dengan Kaum Zaibatsu",
  "JAP_ally_with_the_zaibatsus_desc": "Konglomerat terbesar di negara kita telah lama memiliki pengaruh politik dan ekonomi yang luar biasa. Mereka adalah bukti nyata dari peluang yang dihadirkan oleh kebebasan dan individualitas, dan kita harus bekerja sama dengan mereka demi kemaslahatan bangsa.",
  "JAP_research_spending": "Alokasi Anggaran Riset",
  "JAP_research_spending_desc": "Anggaran yang cukup besar harus dialokasikan untuk penelitian dan pengembangan, jika kita ingin memanfaatkan bakat putra-putri terbaik bangsa kita secara optimal.",
  "JAP_pre_emptive_coup": "Kudeta Preemtif",
  "JAP_pre_emptive_coup_desc": "Kita harus bertindak cepat demi mengamankan masa depan bangsa bagi anak cucu kita, jangan sampai cita-cita kemerdekaan kita diberangus oleh rezim otoriter.",
  "JAP_purge_the_militarists": "Bersihkan Kaum Militeris",
  "JAP_purge_the_militarists_desc": "Mereka yang percaya bahwa kekuatan militer adalah jawaban dari segala persoalan harus dibersihkan dari kepulauan kita demi memberi ruang bagi pemikiran yang lebih berkepala dingin. Mereka dapat mencari jalan hidup mereka sendiri di luar batas wilayah kita.",
  "JAP_the_showa_constitution": "Konstitusi Showa",
  "JAP_the_showa_constitution_desc": "Kita menerima dan menghormati sejarah kekaisaran bangsa kita. Namun, otoritarianisme tidak memiliki tempat di Jepang yang ingin kita bangun. Kita akan mempertahankan Kaisar sebagai simbol pemersatu bangsa, namun membatasi kekuasaannya dalam konstitusi, sebagaimana lazimnya di banyak negara demokrasi Barat.",
  "JAP_west_pacific_treaty_organization": "Pakta Pertahanan Pasifik Barat (WPTO)",
  "JAP_west_pacific_treaty_organization_desc": "Aliansi tersendiri bersama bangsa-bangsa Asia lainnya akan memungkinkan kita berdiri tegak membendung setiap potensi ancaman terhadap tatanan hidup baru kita.",
  "JAP_rekindle_the_old_alliance": "Hidupkan Kembali Aliansi Lama",
  "JAP_rekindle_the_old_alliance_desc": "Peluang terbaik kita berada di tangan sekutu lama kita semasa Perang Besar. Kita akan mengaktifkan kembali aliansi bersejarah tersebut dan berdiri bersama [ENG.GetNameDef] dalam membela panji demokrasi.",
  "JAP_pacific_guardian": "Penjaga Pasifik",
  "JAP_pacific_guardian_desc": "Kita akan mengemban peran sebagai pelindung seluruh negara Asia di lingkar Pasifik. Setelah terbebas dari cengkeraman imperialisme Barat, mereka memerlukan bimbingan bersahabat demi tumbuh menjadi negara demokrasi yang matang.",
  "JAP_anti_communist_bulwark": "Benteng Anti-Komunis",
  "JAP_anti_communist_bulwark_desc": "Prinsip-prinsip luhur demokrasi bertentangan mutlak dengan komunisme. Kita harus berdiri teguh melawan ideologi tersebut, demi melindungi diri kita sendiri serta bangsa-bangsa yang menaruh harapan pada kita.",
  "JAP_anti_communist_volunteers": "Sukarelawan Anti-Komunis",
  "JAP_anti_communist_volunteers_desc": "Kita harus memerangi komunisme di mana pun ia berada, bahkan jika kita sendiri tidak terlibat secara resmi dalam konflik tersebut. Kita akan mengirimkan pasukan sukarelawan untuk memperjuangkan kebebasan di front-front tersebut.",
  "JAP_the_korean_question": "Persoalan Korea",
  "JAP_the_korean_question_desc": "Kita telah lama menguasai semenanjung Korea, namun tuntutan hak penentuan nasib sendiri bangsa Korea kian mendesak. Apakah kita pantas mengaku menjunjung cita-cita demokrasi jika kita merampas hak tetangga kita untuk memerintah tanah air mereka sendiri?",
  "JAP_liberate_manchuria": "Bebaskan Manchuria",
  "JAP_liberate_manchuria_desc": "Manchuria terus hidup di bawah tirani otoriter; sebuah peninggalan kelam dari masa penjajahan kita. Kita harus memperbaiki kekeliruan sejarah ini dan memastikan wilayah tersebut dikembalikan kepada kedaulatan bangsa Tionghoa yang berhak.",
  "JAP_liberate_manchuria_tt": "Keputusan ini dapat diambil setelah menaklukkan Manchuria.\n",
  "JAP_ultimate_deterrence": "Daya Tangkal Mutlak (Ultimate Deterrence)",
  "JAP_ultimate_deterrence_desc": "Cara terbaik untuk melindungi rakyat kita adalah memastikan mereka tidak pernah terseret ke dalam kancah perang. Pengembangan senjata baru dengan daya hancur dahsyat akan menjamin mereka tak perlu lagi memikul derita pertempuran.",
  "JAP_full_sovereignty_for_the_philippines": "Kedaulatan Penuh bagi Filipina",
  "JAP_full_sovereignty_for_the_philippines_desc": "Hak penentuan nasib sendiri harus diperluas ke seantero Asia. [USA.GetNameDefCap] masih terus menguasai Filipina, dan harus ditekan agar menghormati hak-hak demokratis rakyat Filipina.",
  "JAP_the_manchurian_project": "Proyek Manchuria",
  "JAP_the_manchurian_project_desc": "Di saat tanah di kepulauan kita sangat terbatas, wilayah kekuasaan kita di daratan benua terbentang luas. Apa yang tak sanggup kita bangun di tanah air, dapat kita bangun di daratan Manchuria. Kita akan memulai program industrialisasi berskala raksasa bagi [MAN.GetNameDef].",
  "JAP_expand_the_showa_steel_works": "Perluas Pabrik Baja Showa",
  "JAP_expand_the_showa_steel_works_desc": "Kita harus memperluas Pabrik Baja Showa demi melipatgandakan produksinya, sebagai prasyarat krusial bagi industrialisasi skala besar.",
  "JAP_develop_aluminum_sources": "Kembangkan Sumber Aluminium",
  "JAP_develop_aluminum_sources_desc": "Program penerbangan tempur kita membutuhkan pasokan aluminium melimpah, sehingga cadangan bauksit Manchuria harus dieksploitasi secara intensif.",
  "JAP_expand_manchurian_railways": "Perluas Jaringan Rel Manchuria",
  "JAP_expand_manchurian_railways_desc": "Infrastruktur kereta api Manchuria membutuhkan ekspansi drastis untuk mengangkut beban industrialisasi yang kian pesat.",
  "JAP_light_industry_development": "Pengembangan Industri Ringan",
  "JAP_light_industry_development_desc": "Pabrik-pabrik barang konsumsi dan perkakas ringan akan menciptakan lapangan kerja dan menopang perekonomian daerah.",
  "JAP_heavy_industry_development": "Pengembangan Industri Berat",
  "JAP_heavy_industry_development_desc": "Pembangunan pabrik mesin berat, peleburan logam, dan kimia dasar akan melengkapi rantai produksi industri kita di Manchuria.",
  "JAP_japanese_settlement": "Pemukiman Jepang",
  "JAP_japanese_settlement_desc": "Dengan memukimkan warga negara kita sendiri di Manchuria, kita dapat menambah angkatan kerja terlatih sekaligus menciptakan sentra-sentra industri baru yang strategis.",
  "JAP_fortify_the_border": "Bentengi Perbatasan",
  "JAP_fortify_the_border_desc": "Perbatasan utara praktis tidak memiliki pertahanan memadai. Kita harus membangun kubu-kubu pertahanan utara demi mengantisipasi potensi serangan dari arah ini.",
  "JAP_army_expansion_law": "Undang-Undang Ekspansi Angkatan Darat",
  "JAP_army_expansion_law_desc": "Pemerintahan kita harus menetapkan peningkatan drastis kekuatan angkatan bersenjata sebagai salah satu prinsip utamanya.",
  "JAP_small_arms_modernization": "Modernisasi Senjata Ringan",
  "JAP_small_arms_modernization_desc": "Pasukan kita membutuhkan senapan modern agar sanggup menandingi persenjataan musuh potensial kita.",
  "JAP_supremacy_of_technology": "Keunggulan Teknologi",
  "JAP_supremacy_of_technology_desc": "Teknologilah yang akan membawa kita menuju kemenangan mutlak. Segala daya upaya harus diarahkan untuk mengungguli persenjataan dan perlengkapan musuh.",
  "JAP_modern_artillery": "Artileri Modern",
  "JAP_modern_artillery_desc": "Betapa pun gagah beraninya prajurit kita, mereka membutuhkan daya gempur artileri superior demi melapangkan gerak maju di medan laga.",
  "JAP_armored_divisions": "Divisi Lapis Baja",
  "JAP_armored_divisions_desc": "Bangsa-bangsa lain telah menyadari kedahsyatan divisi lapis baja. Kita pantang tertinggal, dan harus merancang tank yang lebih canggih dan bertenaga agar sanggup menghantam musuh dengan cepat dan mematikan.",
  "JAP_bicycle_battalions": "Batalion Sepeda",
  "JAP_bicycle_battalions_desc": "Mobilitas adalah kunci kemenangan. Pasukan infanteri kita akan diperlengkapi dengan sepeda militer, melipatgandakan kecepatan gerak manuver divisi melintasi medan berhutan dan jalan sempit.",
  "JAP_army_expansion": "Ekspansi Angkatan Darat",
  "JAP_army_expansion_desc": "Demi memperluas kekuatan militer, kita harus mendayagunakan keahlian para perwira berpengalaman yang terbukti piawai melatih prajurit dalam seni peperangan.",
  "JAP_supremacy_of_will": "Keunggulan Tekad (Seishin)",
  "JAP_supremacy_of_will_desc": "Peralatan tercanggih tak ada artinya tanpa jiwa kesatria yang membara di dada penggunanya, dan tekad baja sanggup mengubah batu sederhana menjadi senjata paling mematikan.",
  "JAP_fighter_modernization": "Modernisasi Pesawat Tempur",
  "JAP_fighter_modernization_desc": "Kita harus mempertahankan keunggulan mutlak atas lawan di segala matra, termasuk perang udara. Pesawat tempur modern sangat krusial untuk mencapainya.",
  "JAP_range_focus": "Fokus Jarak Jangkau",
  "JAP_range_focus_desc": "Jarak geografis dalam gelanggang perang Pasifik teramat luas, maka kita memerlukan pesawat yang sanggup menembus jarak ribuan mil laut tersebut.",
  "JAP_agility_focus": "Fokus Kelincahan",
  "JAP_agility_focus_desc": "Jarak jangkau jauh tak berguna jika pesawat kita kalah lincah saat duel udara dengan lawan. Kita harus memproduksi pesawat dengan kemampuan manuver tak tertandingi.",
  "JAP_the_zero": "Sang Legenda Zero",
  "JAP_the_zero_desc": "Rancangan revolusioner dari Mitsubishi terbukti sebagai pesawat tempur berbasis kapal induk paling mematikan yang pernah diciptakan manusia. Kelincahan luar biasa dipadu jarak jangkau jauh akan mendominasi angkasa selama bertahun-tahun. Kita harus segera memproduksinya secara massal.",
  "JAP_the_zero_tt": "Membuka produksi §HMitsubishi A6M Zero-sen§!",
  "JAP_bomber_modernization": "Modernisasi Pesawat Pembom",
  "JAP_bomber_modernization_desc": "Armada pembom taktis modern adalah kunci utama dalam memberikan bantuan tembakan bagi pasukan darat kita di medan tempur.",
  "JAP_strategic_bomber_effort": "Pengembangan Pembom Strategis",
  "JAP_strategic_bomber_effort_desc": "Betapa pun kita ingin, perang tidak dapat dimenangkan semata-mata lewat bentrokan langsung di garis depan. Kapasitas industri menentukan hasil akhir perang, sehingga kita harus berinvestasi pada armada pembom strategis untuk melumat sentra industri musuh di garis belakang.",
  "JAP_unified_fighter_development": "Penyatuan Riset Pesawat Tempur",
  "JAP_unified_fighter_development_desc": "Terlalu lama kita dirugikan oleh persaingan tidak sehat antara penerbangan Angkatan Darat dan Angkatan Laut. Kita harus menyatukan program riset ini demi standardisasi persenjataan dan efisiensi sumber daya litbang.",
  "JAP_jet_prototypes": "Purwarupa Mesin Jet",
  "JAP_jet_prototypes_desc": "Masa depan penerbangan bukan lagi milik baling-baling. Kita harus mengembangkan tenaga penggerak jet demi melipatgandakan kecepatan pesawat kita.",
  "JAP_new_naval_estimates": "Rencana Anggaran Angkatan Laut Baru",
  "JAP_new_naval_estimates_desc": "Kita harus menyusun kalkulasi baru mengenai perluasan armada kapal perang kita, serta fasilitas galangan kapal yang dibutuhkan untuk merealisasikannya.",
  "JAP_carrier_warfare_experiments": "Eksperimen Perang Kapal Induk",
  "JAP_carrier_warfare_experiments_desc": "Kapal tempur adalah peninggalan era lampau. Masa depan peperangan samudra bertumpu pada penerbangan tempur laut. Kapal induk memungkinkan kita memproyeksikan kekuatan udara ke seberang Samudra Pasifik.",
  "JAP_expand_the_snlf": "Perluas Pasukan Pendarat Laut Khusus (SNLF)",
  "JAP_expand_the_snlf_desc": "Peperangan di kepulauan Pasifik akan sangat bergantung pada operasi pendaratan amfibi. Pasukan Khusus Pendarat Angkatan Laut harus diperbesar agar sanggup mengemban misi berat ini.",
  "JAP_first_air_fleet": "Armada Udara Pertama (Kido Butai)",
  "JAP_first_air_fleet_desc": "Demi memaksimalkan daya hancur ofensif, kita akan menghimpun konsentrasi kapal induk terbesar dalam sejarah peradaban ke dalam satu gugus tempur pemukul. Dengan mematangkan doktrin operasi ofensif terpadu ini, armada musuh tak akan berkutik di hadapan kedahsyatan penerbangan tempur kita.",
  "JAP_modern_escorts": "Kapal Pengawal Modern",
  "JAP_modern_escorts_desc": "Armada tempur kita memerlukan kapal-kapal pengawal paling modern demi beroperasi leluasa tanpa gangguan dari kapal selam dan kapal torpedo musuh.",
  "JAP_supremacy_of_the_battlefleet": "Keunggulan Armada Tempur Utama (Kantai Kessen)",
  "JAP_supremacy_of_the_battlefleet_desc": "Berbekal rancangan kapal tempur superior kita, kita hanya membutuhkan satu bentrokan laut yang menentukan untuk mengunci kemenangan mutlak. Kita harus mengoptimalkan armada tempur agar mampu memaksakan dan memenangkan pertempuran tersebut.",
  "JAP_the_ultimate_battleship": "Kapal Tempur Pamungkas",
  "JAP_the_ultimate_battleship_desc": "Karena kita tidak kaya sumber daya, kita harus memanfaatkannya untuk kapal terhebat. Kita akan membangun kapal tempur terbesar dan paling perkasa yang pernah mengapung di muka bumi, sanggup melumat musuh mana pun dalam duel terbuka.",
  "JAP_cruiser_modernization": "Modernisasi Kapal Penjelajah",
  "JAP_cruiser_modernization_desc": "Kapal penjelajah akan menjadi tulang punggung gugus tugas kita di seantero Pasifik, sehingga kita memerlukan rancangan terbaik yang mampu kita bangun.",
  "JAP_long_lance_torpedoes": "Torpedo Long Lance (Tipe 93)",
  "JAP_long_lance_torpedoes_desc": "Ketidakseimbangan sumber daya global membuat armada kita kalah jumlah oleh musuh. Oleh karena itu, kita akan merancang torpedo tercanggih di dunia: senjata berdaya hancur dahsyat dengan jarak jangkau luar biasa jauh yang didorong oleh oksigen murni, memungkinkan kapal permukaan kecil kita menghancurkan kapal raksasa musuh dari jarak aman.",
  "JAP_torpedo_cruisers": "Penjelajah Torpedo",
  "JAP_torpedo_cruisers_desc": "Kita akan mengkhususkan satu kelas kapal perang untuk membawa puluhan torpedo baru kita, memungkinkan mereka memuntahkan badai torpedo mematikan ke tengah konvoi armada musuh.",
  "JAP_yamato_tt": "Menambahkan dua jalur produksi Kapal Tempur Super-Berat §YKelas Yamato§!, masing-masing selesai 75% dan 50%.",
  "cost_reduced_last_stand": "Mengizinkan penggunaan kemampuan komando §YBertahan Sampai Akhir (Last Stand)§! dengan pengurangan biaya yang signifikan.\n",
  "MAN_pacify_the_countryside": "Pasifikasi Pedalaman",
  "MAN_pacify_the_countryside_desc": "Sejak kita naik ke tampuk kekuasaan, para bandit dan pemberontak terus merongrong kekuasaan kita di wilayah pelosok negeri. Jika kita ingin dihormati sebagai pemerintahan yang berwibawa, kita harus menumpas tuntas gerombolan ini dan membuktikan kepada rakyat bahwa kita sanggup menegakkan hukum.",
  "MAN_pacify_the_countryside_effect_tooltip": "Tempatkan pasukan di negara bagian tertentu untuk menetralkan bandit di pedalaman.\n",
  "MAN_army_modernization": "Modernisasi Angkatan Darat",
  "MAN_army_modernization_desc": "Angkatan Darat kita kecil dan ketinggalan zaman. Mengingat potensi sumber daya kita, hal ini tidak bisa diterima. Kita harus sanggup memikul tanggung jawab kita secara mandiri.",
  "MAN_mukden_military_academy": "Akademi Militer Mukden",
  "MAN_mukden_military_academy_desc": "Tentara kita membutuhkan perwira-perwira setia dan cakap jika kita ingin mengandalkan taktik dan disiplin daripada sekadar jumlah massa untuk meraih kemenangan.",
  "MAN_invite_japanese_settlers": "Undang Transmigran Jepang",
  "MAN_invite_japanese_settlers_desc": "Lahan kita jauh lebih luas daripada jumlah penduduk kita. Sebagian besar wilayah negeri masih berupa padang belantara. Kita harus mendatangkan pemukim ke daerah-daerah ini demi membangun komunitas baru dan mempercepat pembangunan ekonomi.",
  "MAN_collective_farms": "Pertanian Kolektif",
  "MAN_collective_farms_desc": "Sistem pertanian perorangan yang dikelola oleh satu keluarga kecil terbukti terbelakang dan tidak efisien. Menyatukan tenaga kerja dan lahan satu desa ke dalam satu kesatuan akan memungkinkan modernisasi yang jauh lebih produktif.",
  "MAN_law_university": "Universitas Hukum",
  "MAN_law_university_desc": "Negara kita masih belia. Kita memiliki peluang emas untuk menyusun sistem hukum yang benar-benar baru, berlandaskan pemahaman kenegaraan paling modern. Untuk itu, kita harus mendirikan lembaga pendidikan tinggi guna menghimpun para pemikir paling cemerlang di Asia.",
  "MAN_research_and_education_department": "Departemen Riset dan Pendidikan",
  "MAN_research_and_education_department_desc": "Seiring tumbuhnya bangsa kita, sarana pendidikan dan riset kita harus dikembangkan sepadan. Upaya lebih besar harus dikerahkan guna memastikan fokus penelitian diarahkan tepat pada sektor-sektor yang paling membutuhkan.",
  "MAN_trade_delegation": "Delegasi Perdagangan",
  "MAN_trade_delegation_desc": "Dunia luar jauh lebih maju dalam penguasaan metode industri modern. Kita harus mengirimkan delegasi dagang untuk mempelajari teknik-teknik mereka guna memperbaiki sistem kita sendiri.",
  "MAN_expand_the_textile_industry": "Perluas Industri Tekstil",
  "MAN_expand_the_textile_industry_desc": "Pabrik-pabrik tekstil kita sekian lama menjadi andalan manufaktur negeri, dan merupakan cara paling cepat untuk meraup modal asing demi memperluas basis industri berat kita.",
  "MAN_obedience": "Ketaatan pada Sekutu",
  "MAN_obedience_desc": "Segelintir pihak mencap kita sekadar boneka Jepang, namun mereka sama sekali tidak memahami ikatan erat dan kesetaraan hubungan kita. Melawan para penyokong kita sama hinanya dengan anak yang durhaka kepada orang tuanya.",
  "MAN_hoankyoku": "Hoankyoku (Biro Keamanan Politik)",
  "MAN_hoankyoku_desc": "Pemerintahan kita adalah harapan terbaik bagi masa depan Tiongkok. Tak pelak lagi, banyak pihak bernafsu menghancurkannya. Kita harus membentuk dinas keamanan khusus yang bertugas memburu para pengacau tersebut dan melindungi keutuhan negara.",
  "MAN_first_five_year_plan": "Rencana Lima Tahun Pertama",
  "MAN_first_five_year_plan_desc": "Kendati kerap dikaitkan dengan komunisme, rencana lima tahun adalah instrumen berharga dalam merancang pembangunan ekonomi nasional. Kita harus menerapkan rencana ini demi memandu ekspansi industri kita secara terukur.",
  "MAN_invite_japanese_investors": "Undang Investor Jepang",
  "MAN_invite_japanese_investors_desc": "Membangun negeri memerlukan modal dari luar. Sejumlah konglomerat di Jepang telah menyatakan kesediaan mereka menanamkan modal di negara kita.",
  "MAN_expand_the_railways": "Perluas Jaringan Rel Kereta Api",
  "MAN_expand_the_railways_desc": "Jaringan kereta api modern adalah urat nadi yang menyatukan setiap sudut negeri kita di bawah satu naungan.",
  "MAN_develop_aluminum_sources": "Kembangkan Sumber Aluminium",
  "MAN_develop_aluminum_sources_desc": "Kita memiliki deposit bauksit melimpah di Liaoning yang siap ditambang. Kekayaan ini akan menjadi suntikan tenaga luar biasa bagi industri penerbangan kita.",
  "MAN_expand_showa_steel_works": "Perluas Pabrik Baja Showa",
  "MAN_expand_showa_steel_works_desc": "Pabrik Baja Showa merupakan tulang punggung industri berat kita. Berinvestasi di sana akan mendatangkan keuntungan melimpah bagi kemandirian bangsa di kemudian hari.",
  "MAN_social_research_unit": "Unit Riset Sosial",
  "MAN_social_research_unit_desc": "Kita harus membentuk unit khusus untuk meneliti adat istiadat dan perilaku rakyat kita, agar kita dapat membimbing mereka menjadi warga negara yang patuh dan berdaya guna.",
  "MAN_second_five_year_plan": "Rencana Lima Tahun Kedua",
  "MAN_second_five_year_plan_desc": "Menyusul kesuksesan Rencana Lima Tahun Pertama, sudah selayaknya kita melanjutkan momentum pembangunan ekonomi ini ke tahap berikutnya.",
  "MAN_national_defense_state": "Negara Pertahanan Nasional",
  "MAN_national_defense_state_desc": "Hingga perang ini dimenangkan dan kita kembali bertahta atas seluruh Tiongkok, kita harus mengerahkan segenap daya, rela berkorban jiwa raga, dan mendayagunakan seluruh sumber daya untuk memenangkan perang.",
  "MAN_mukden_arsenal": "Pabrik Persenjataan Mukden",
  "MAN_mukden_arsenal_desc": "Pabrik senjata lama Kekaisaran akan menjadi inti dari kompleks industri militer baru yang akan memasok persenjataan modern bagi tentara kita.",
  "MAN_mamc": "MAMC (Perusahaan Manufaktur Pesawat Manchuria)",
  "MAN_mamc_desc": "Mendirikan Perusahaan Manufaktur Pesawat Manchuria akan memberi kita sarana untuk membangun angkatan udara modern yang sanggup berdiri sejajar dengan negara mana pun.",
  "MAN_alliance_with_the_kwantung_army": "Aliansi dengan Tentara Kwantung",
  "MAN_alliance_with_the_kwantung_army_desc": "Pasukan militer Jepang di negeri kita kerap berselisih paham dengan gagasan kita. Kita harus menjalin kemitraan yang lebih erat dengan mereka demi memastikan kerja sama berjalan mulus tanpa gesekan.",
  "MAN_chinese_leadership": "Kepemimpinan Sejati Tiongkok",
  "MAN_chinese_leadership_desc": "Rakyat Tiongkok merindukan pemimpin sejati keturunan Tionghoa. Kita harus menyatakan secara terbuka kepada dunia bahwa cita-cita kita adalah pemulihan penuh Dinasti Kekaisaran atas seluruh daratan Tiongkok!",
  "MAN_vassalize_mengukuo": "Tundukkan Mengkukuo",
  "MAN_vassalize_mengukuo_desc": "Pangeran Mengkukuo tidak pantas disejajarkan dengan Kaisar Manchukuo. Waktunya telah tiba untuk mengakhiri eksperimen ini dan menempatkan beliau pada kedudukan vasal yang semestinya.",
  "MAN_national_cooperation_government": "Pemerintahan Kerja Sama Nasional",
  "MAN_national_cooperation_government_desc": "Kita mendengar desas-desus meresahkan bahwa Jepang tengah mempertimbangkan politisi Tionghoa lain — rakyat jelata — untuk membentuk pemerintahan kolaborasi. Ini penghinaan yang tak bisa ditoleransi. Kita harus memastikan seluruh wilayah Tiongkok yang dibebaskan dikelola langsung oleh kita!",
  "MAN_the_two_emperors": "Dua Kaisar Bersaudara",
  "MAN_the_two_emperors_desc": "Saatnya membuang anggapan keliru bahwa kita hanyalah bawahan Jepang. Dua Kaisar kita berdiri sejajar bagaikan saudara kandung yang saling menghormati!",
  "MAN_assertiveness": "Kemandirian Tegas (Assertiveness)",
  "MAN_assertiveness_desc": "Pihak Jepang terus bersikap arogan dan memperlakukan kita semena-mena. Kita harus mengingatkan mereka bahwa kita pun sebuah Kekaisaran berdaulat yang patut disegani.",
  "MAN_request_control_of_the_railways": "Tuntut Kendali Kereta Api",
  "MAN_request_control_of_the_railways_desc": "Di negeri seluas wilayah kita, menguasai rel kereta api berarti menguasai jalannya negara.\n\nDan saat ini pihak Jepang yang menguasai perkeretaapian itu.\n\nKeadaan tersebut harus diakhiri.",
  "MAN_staff_the_court_with_manchus": "Isi Istana dengan Bangsawan Manchu",
  "MAN_staff_the_court_with_manchus_desc": "Dinasti Qing telah memimpin Tiongkok selama berabad-abad. Jika kita ingin merebut kembali keagungan masa lalu kita, kita harus memastikan kita meneladani tata kelola istana leluhur kita sedekat mungkin.",
  "MAN_expand_the_imperial_guards": "Perluas Pasukan Pengawal Kekaisaran",
  "MAN_expand_the_imperial_guards_tt": "Dapatkan 4 unit dengan §Y7 batalion Infanteri§! dan §Y2 batalion Artileri§!.\n",
  "MAN_expand_the_imperial_guards_desc": "Pasukan Pengawal Kekaisaran akan menjadi korps elit angkatan darat kita yang menjadi teladan pengabdian bagi seluruh prajurit.",
  "MAN_local_arms_procurement": "Pengadaan Senjata Mandiri",
  "MAN_local_arms_procurement_desc": "Kita tidak bisa selamanya bergantung pada belas kasihan pasokan senjata Jepang. Jika kita ingin berdaulat, kita harus memegang pabrik senjata kita sendiri.",
  "MAN_bolster_nationalism": "Kobarkan Nasionalisme",
  "MAN_bolster_nationalism_desc": "Sekian lama khalayak memandang Manchukuo sekadar ciptaan artifisial bentukan Jepang. Namun setiap bangsa besar bermula dari sebuah gagasan. Kita harus membangkitkan rasa identitas kebangsaan Manchu di hati rakyat dan mengubah gagasan itu menjadi kenyataan agung.",
  "MAN_five_equal_peoples": "Lima Bangsa yang Setara",
  "MAN_five_equal_peoples_desc": "Zaman ketika satu etnis mendominasi dan menindas etnis lainnya telah berlalu. Manchukuo akan menjadi fajar baru sebuah bangsa, di mana lima suku bangsa — Rusia, Jepang, Mongolia, Korea, dan Manchu — hidup berdampingan dalam harmoni persaudaraan.",
  "MAN_white_russian_advisers": "Penasihat Militer Rusia Putih",
  "MAN_white_russian_advisers_desc": "Pasca-perang saudara di Rusia, ribuan warga Rusia Putih memilih mengungsi ke tanah kita daripada menghadapi pembantaian kaum Bolshevik. Kita dapat mendayagunakan keahlian tempur para perwira berpengalaman ini untuk melatih angkatan perang kita.",
  "MAN_empower_the_legislative_council": "Berdayakan Dewan Legislatif",
  "MAN_empower_the_legislative_council_desc": "Dewan Legislatif saat ini hanyalah stempel seremonial yang menyetujui apa pun yang disodorkan oleh tuan Jepang kita. Jika kita ingin menjadi negara berdaulat sejati, kita harus memegang otonomi mutlak dalam urusan perundang-undangan.",
  "MAN_five_people_armies": "Laskar Lima Bangsa",
  "MAN_five_people_armies_desc": "Jika setiap warga negara memiliki derajat yang setara, maka setiap warga negara wajib sama-sama siap membela kedaulatan tanah air dari penindasan asing.",
  "MAN_five_people_armies_tt": "Dapatkan 7 unit dengan §Y3 batalion Infanteri§!.\n",
  "MAN_purge_the_general_affairs_council": "Bubarkan Dewan Urusan Umum",
  "MAN_purge_the_general_affairs_council_desc": "Dewan Urusan Umum sengaja disusupkan oleh Jepang demi memegang kendali penuh atas pemerintahan kita. Tirani tersembunyi ini tidak boleh dibiarkan. Kita harus menyingkirkan siapa pun yang kesetiaannya pada negara kita diragukan!",
  "MAN_reform_the_civil_service": "Reformasi Aparatur Sipil",
  "MAN_reform_the_civil_service_desc": "Dewan Urusan Umum barulah puncak gunung es. Para birokrat Jepang praktis mengendalikan sebagian besar instansi sipil di luar kendali kita. Kita harus menempatkan para pamong praja kita sendiri di pos-pos penting.",
  "MAN_independence_war": "Perang Kemerdekaan",
  "MAN_independence_war_desc": "Waktunya telah tiba untuk mematahkan belenggu penindasan dan bertarung demi kemerdekaan pusaka leluhur kita. Manchukuo akan menjadi tanah Tiongkok pertama yang menghirup udara kebebasan dari cengkeraman penjajah!",
  "MAN_imperial_divinity": "Kesucian Takhta Kekaisaran",
  "MAN_imperial_divinity_desc": "Di masa lampau, para Kaisar Tiongkok diagungkan sebagai Putra Langit pembawa amanat suci. Kita harus menautkan kembali kedudukan Yang Mulia Kaisar saat ini dengan tradisi agung tersebut.",
  "MAN_imperial_university": "Universitas Kekaisaran",
  "MAN_imperial_university_desc": "Kekaisaran membutuhkan cendekiawan berbakat untuk memperjuangkan kejayaannya. Kita harus mendirikan universitas agung tempat putra-putri terbaik bangsa saling menuntut ilmu dan berinovasi.",
  "MAN_move_capitals": "Pindahkan Ibu Kota",
  "MAN_move_capitals_desc": "Ibu kota kuno seluruh Tiongkok sejak zaman dahulu adalah Beijing. Kini setelah kota tersebut berhasil kita rebut kembali, kita dapat mengarak Sang Kaisar dalam pawai kemenangan kembali ke istana leluhur beliau.",
  "MAN_claim_the_mandate_of_heaven": "Klaim Mandat Langit (Tianming)",
  "MAN_claim_the_mandate_of_heaven_desc": "Kemenangan gemilang kita dalam perang membuktikan bahwa langit sendiri telah merestui Yang Mulia Kaisar sebagai penguasa yang adil dan berhak atas Takhta Surgawi. Setiap keraguan akan keabsahan beliau sebagai penguasa tunggal seluruh Tiongkok akan sirna di hadapan bukti nyata yang tak terbantahkan ini!",
  "MAN_reclaim_the_empire": "Rebut Kembali Kekaisaran",
  "MAN_reclaim_the_empire_desc": "Kini setelah kita memenangkan kemerdekaan sejati, saatnya meneruskan perang suci menumpas para pengkhianat dan pemberontak di seantero Tiongkok. Kita akan bertahta atas negeri ini, atau gugur sebagai kesatria dalam mencapainya!",
  "MAN_assert_our_authority": "Tegakkan Otoritas Kekaisaran",
  "MAN_assert_our_authority_desc": "Seluruh penjuru negeri kini terpecah-belah oleh anarki. Tak satu pun dari para perampas kekuasaan dan bandit yang menggelari diri mereka panglima perang maupun ketua faksi yang pantas memimpin bangsa. Mereka akan dipaksa berlutut, dan cahaya kepemimpinan agung kita akan menyinari seluruh Tiongkok!",
  "MAN_offer_vassalization": "Tawarkan Status Vasal",
  "MAN_offer_vassalization_desc": "Kobaran perang telah mencabik-cabik persatuan tanah air. Kita dapat memadamkannya jika kita menawarkan tempat terhormat di istana bagi mereka yang selama ini enggan memihak pemberontak."
}

